            Expect.Do("one empty", () => { Expect.Eq("one empty", SameTree.Check(Build(1), null), false); });
        } catch (Exception e) { Expect.Setup(e); }
        Expect.Summary(7);
    }

    // helpers used by the examples
    static TreeNode Build(params int?[] level) {
        if (level.Length == 0 || level[0] == null) return null;
        var root = new TreeNode(level[0].Value); var q = new Queue<TreeNode>(); q.Enqueue(root); int i = 1;
        while (q.Count > 0 && i < level.Length) {
            var n = q.Dequeue();
            if (i < level.Length && level[i] != null) { n.Left = new TreeNode(level[i].Value); q.Enqueue(n.Left); } i++;
            if (i < level.Length && level[i] != null) { n.Right = new TreeNode(level[i].Value); q.Enqueue(n.Right); } i++;
        }
        return root;
    }
    static string Lv(TreeNode root) {          // level order, "null" for gaps, trailing nulls dropped
        var parts = new List<string>(); var q = new Queue<TreeNode>(); q.Enqueue(root);
        while (q.Count > 0) { var n = q.Dequeue(); if (n == null) { parts.Add("null"); continue; } parts.Add(n.Value.ToString()); q.Enqueue(n.Left); q.Enqueue(n.Right); }
        while (parts.Count > 0 && parts[parts.Count - 1] == "null") parts.RemoveAt(parts.Count - 1);
        return "[" + string.Join(",", parts) + "]";
    }
    static TreeNode Node(TreeNode r, int v) {  // find a node by value
        var s = new Stack<TreeNode>(); if (r != null) s.Push(r);
        while (s.Count > 0) { var n = s.Pop(); if (n.Value == v) return n; if (n.Left != null) s.Push(n.Left); if (n.Right != null) s.Push(n.Right); }
        return null;
    }
    static TreeNode Chain(int n) { var root = new TreeNode(0); var c = root; for (int i = 1; i < n; i++) { c.Right = new TreeNode(i); c = c.Right; } return root; }
}

// The example checker. ✓ = your result matches, ✗ = it does not (or the method is not written yet).
static class Expect {
    static int pass, fail;
    static string Show(object o) => o is string s ? "\"" + s + "\"" : (o?.ToString() ?? "null");
    static void Report(bool ok, string what, string got, string want) {
        if (ok) { pass++; Console.WriteLine("✓ " + what); }
        else { fail++; Console.WriteLine("✗ " + what + "\n    got  " + got + "\n    want " + want); }
    }
    public static void Eq<TV>(string what, TV got, TV want) => Report(EqualityComparer<TV>.Default.Equals(got, want), what, Show(got), Show(want));
    public static void True(string what, bool ok) => Report(ok, what, ok.ToString(), "True");
    public static void Seq<TV>(string what, IEnumerable<TV> got, params TV[] want) {
        var g = got == null ? new List<TV>() : new List<TV>(got);
        bool ok = g.Count == want.Length;
        for (int i = 0; ok && i < g.Count; i++) ok = EqualityComparer<TV>.Default.Equals(g[i], want[i]);
        Report(ok, what, "[" + string.Join(", ", g) + "]", "[" + string.Join(", ", want) + "]");
    }
    public static void Throws<TE>(string what, Action a) where TE : Exception {
        try { a(); Report(false, what, "no exception", typeof(TE).Name); }
        catch (TE) { Report(true, what, "", ""); }
    }
    // Runs one example; a crash or a missing method is a ✗, and the next example still runs.
